const response = $input.item.json.response;
const lines = response.split('\n').filter(l => l.trim());
const firstLine = lines[0] || response;

const match = firstLine.match(/^(\w+)(\(([^)]+)\))?:\s*(.+)$/);
let type = 'feat', scope = '', description = firstLine;
if (match) { type = match[1]; scope = match[3] || ''; description = match[4]; }

return {
  json: {
    mensaje: response,
    tipo: type,
    alcance: scope,
    descripcion: description,
    tieneBreakingChanges: response.toLowerCase().includes('breaking change'),
    timestamp: new Date().toISOString()
  }
};
